package dev.halloween;
import java.util.*;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.server.world.ServerWorld;
import net.minecraft.entity.*;
import net.minecraft.text.Text;
import net.minecraft.util.ActionResult;
import net.minecraft.util.math.*;
/** Rest advances ordinary train simulation; it never changes respawn points or teleports trains. */
final class RailRest {
 record Berth(Box box,Vec3d pillow){}
 static final class Trip {final RailSeatEntity seat;final RailVehicleEntity engine;final int visit;final long readyAt;final ServerPlayerEntity.Respawn respawn;final float health;boolean arrived;Trip(ServerPlayerEntity p,RailSeatEntity s,RailVehicleEntity e){seat=s;engine=e;visit=e.visits;readyAt=p.getEntityWorld().getTime()+40;respawn=p.getRespawn();health=p.getHealth();}}
 static final Map<ServerPlayerEntity,Trip> REST=new WeakHashMap<>();static boolean ownSprint;static net.minecraft.server.MinecraftServer sprintServer;
 static List<Berth> berths(){var out=new ArrayList<Berth>();for(double c:new double[]{-3.15,0,3.15})for(int side:new int[]{-1,1})for(int top=0;top<2;top++){double y=top==0?1.5:4.29,cap=top==0?1.99:4.60,z=c+side*1.17;out.add(new Berth(new Box(-1.46,y,z-.38,.43,cap,z+.38),new Vec3d(-.52,(top==0?1.92:4.53)+.125,z)));}return out;}
 static boolean isResting(ServerPlayerEntity p){return REST.containsKey(p);}
 static ActionResult begin(ServerPlayerEntity p,RailVehicleEntity coach){var w=p.getEntityWorld();if(Boolean.getBoolean("halloween.sleeperTest"))org.slf4j.LoggerFactory.getLogger("rail-rest").info("TRY position={} local={} time={} mounted={} powered={}",p.getEntityPos(),RailPassengerNetwork.toLocal(coach,p.getEntityPos()),w.getTimeOfDay(),p.hasVehicle(),RailDriver.powered(w,coach.engine()));if(!coach.isSleeper()||p.hasVehicle()||p.isSpectator()||!RailPassengerNetwork.inside(coach,RailPassengerNetwork.toLocal(coach,p.getEntityPos()))||RailPassengerNetwork.toLocal(coach,p.getEntityPos()).x>.4)return ActionResult.FAIL;long time=Math.floorMod(w.getTimeOfDay(),24000);if(time<12500||time>23500){p.sendMessage(Text.literal("Ночной отдых доступен вечером и ночью."),true);return ActionResult.FAIL;}var engine=coach.engine();if(engine==null||engine.route()==null||!engine.route().closed||engine.stationStops.isEmpty()||!RailDriver.powered(w,engine)){p.sendMessage(Text.literal("Нужен поезд с машинистом на маршруте между станциями."),true);return ActionResult.FAIL;}
  var start=RailPassengerNetwork.toLocal(coach,p.getEyePos());var end=start.add(RailGeometry.rotate(p.getRotationVec(1).multiply(p.getEntityInteractionRange()),-coach.getYaw()));Berth selected=null;double nearest=Double.POSITIVE_INFINITY;for(var b:berths()){var hit=b.box.raycast(start,end);if(hit.isPresent()&&hit.get().squaredDistanceTo(start)<nearest){selected=b;nearest=hit.get().squaredDistanceTo(start);}}if(selected==null){p.sendMessage(Text.literal("Наведитесь на нижнюю или верхнюю полку."),true);return ActionResult.FAIL;}
  double remaining=engine.route().wrap(engine.stationStops.get(engine.nextStop)-engine.distance);if(remaining/.4+engine.dwell+500>12000){p.sendMessage(Text.literal("До следующей станции слишком далеко для короткого отдыха."),true);return ActionResult.FAIL;}var pos=RailGeometry.rotate(selected.pillow,coach.getYaw()).add(coach.getEntityPos());if(!w.getOtherEntities(coach,new Box(pos,pos).expand(.35),e->e instanceof RailSeatEntity&&e.hasPassengers()).isEmpty())return ActionResult.FAIL;
  var seat=RailContent.SEAT.create(w,SpawnReason.EVENT);if(seat==null)return ActionResult.FAIL;seat.owner=coach.getUuid();seat.local=selected.pillow;seat.resting(true);seat.setPosition(pos);w.spawnEntity(seat);if(!p.startRiding(seat,true,false)){seat.discard();return ActionResult.FAIL;}p.setSneaking(false);p.setPlayerInput(net.minecraft.util.PlayerInput.DEFAULT);REST.put(p,new Trip(p,seat,engine));seat.syncToTrain();org.slf4j.LoggerFactory.getLogger("rail-rest").info("BEGIN visit={} time={}",engine.visits,w.getTimeOfDay());p.sendMessage(Text.literal("Отдых до следующей станции. Точка возрождения не меняется."),true);return ActionResult.SUCCESS;
 }
 static boolean allReady(Collection<ServerPlayerEntity> players){return players.stream().filter(p->!p.isSpectator()).allMatch(p->p.isSleeping()||REST.containsKey(p));}
 static void register(){net.fabricmc.fabric.api.event.lifecycle.v1.ServerLifecycleEvents.SERVER_STOPPING.register(server->{for(var e:List.copyOf(REST.entrySet()))if(e.getKey().getEntityWorld().getServer()==server){var p=e.getKey();var t=e.getValue();if(t.arrived)t.engine.dwell=300;t.seat.resting(false);p.stopRiding();var coach=t.seat.train();if(coach!=null)p.setPosition(RailGeometry.rotate(new Vec3d(-.3,1.5,RailGeometry.compartmentCenter(t.seat.local.z)),coach.getYaw()).add(coach.getEntityPos()));REST.remove(p);}stopSprint(server);});ServerTickEvents.END_SERVER_TICK.register(server->{if(REST.isEmpty()){stopSprint(server);return;}boolean cancelled=false;for(var e:List.copyOf(REST.entrySet())){var p=e.getKey();var trip=e.getValue();if(p.isDisconnected()||!p.isAlive()||p.getHealth()<trip.health-.01f||p.getVehicle()!=trip.seat||trip.engine.isRemoved()||p.getEntityWorld().getTime()>trip.readyAt+12000||!RailDriver.powered(p.getEntityWorld(),trip.engine)){org.slf4j.LoggerFactory.getLogger("rail-rest").info("CANCEL mounted={} alive={} health={}/{} powered={} now={} ready={}",p.getVehicle()==trip.seat,p.isAlive(),p.getHealth(),trip.health,RailDriver.powered(p.getEntityWorld(),trip.engine),p.getEntityWorld().getTime(),trip.readyAt);REST.remove(p);if(trip.arrived)trip.engine.dwell=300;if(p.getVehicle()==trip.seat)wake(p,trip.seat);cancelled=true;continue;}if(trip.engine.visits>trip.visit){trip.arrived=true;trip.engine.dwell=Integer.MAX_VALUE;}}
   if(cancelled){stopSprint(server);for(var e:List.copyOf(REST.entrySet())){REST.remove(e.getKey());if(e.getValue().arrived)e.getValue().engine.dwell=300;wake(e.getKey(),e.getValue().seat);}return;}
   if(REST.isEmpty())return;boolean allReady=allReady(server.getPlayerManager().getPlayerList());for(var t:REST.values())t.seat.restWaiting(!allReady);if(!allReady){stopSprint(server);return;}
   if(REST.values().stream().allMatch(t->t.arrived)){org.slf4j.LoggerFactory.getLogger("rail-rest").info("ARRIVED; dawn applied from {}",server.getOverworld().getTimeOfDay());stopSprint(server);var w=server.getOverworld();w.setTimeOfDay((w.getTimeOfDay()/24000+1)*24000+1000);for(var e:List.copyOf(REST.entrySet())){var p=e.getKey();var t=e.getValue();REST.remove(p);t.engine.dwell=300;wake(p,t.seat);p.sendMessage(Text.literal("Утро. Поезд прибыл на следующую станцию."),false);if(!Objects.equals(t.respawn,p.getRespawn()))org.slf4j.LoggerFactory.getLogger("rail-rest").warn("Respawn changed externally during rest for {}",p.getUuid());}return;}
   if(!server.getTickManager().isSprinting()&&REST.values().stream().allMatch(t->t.arrived||t.readyAt<=t.engine.getEntityWorld().getTime())){int ticks=1;for(var t:REST.values())if(!t.arrived){double d=t.engine.route().wrap(t.engine.stationStops.get(t.engine.nextStop)-t.engine.distance);ticks=Math.max(ticks,(int)Math.min(12000,d/.4+Math.min(300,t.engine.dwell)+500));}server.getTickManager().startSprint(ticks);org.slf4j.LoggerFactory.getLogger("rail-rest").info("SPRINT {} ticks",ticks);ownSprint=true;sprintServer=server;}
  });}
 static void stopSprint(net.minecraft.server.MinecraftServer server){if(ownSprint&&sprintServer==server){server.getTickManager().stopSprinting();ownSprint=false;sprintServer=null;}}
 static void wake(ServerPlayerEntity p,RailSeatEntity seat){var coach=seat.train();seat.resting(false);if(p.hasVehicle())p.stopRiding();if(coach!=null){var pos=RailGeometry.rotate(new Vec3d(-.3,1.5,RailGeometry.compartmentCenter(seat.local.z)),coach.getYaw()).add(coach.getEntityPos());p.networkHandler.requestTeleport(pos.x,pos.y,pos.z,coach.getYaw(),0);}seat.discard();}
}
